// === Tab: sketch ===
let cols, rows;
let scl = 50;
let w = 1200;
let h = 1000;
let zoff = 0;

function setup() {
  createCanvas(800, 800);
  cols = w / scl;
  rows = h / scl;
  noStroke();
}

function draw() {
  background(240, 210, 150); // tono base cálido carne-amarillo
  translate(width/2, height/2);
  rotate(PI / 4);

  let xoff = 0;
  for (let x = -w/2; x < w/2; x += scl) {
    let yoff = 0;
    for (let y = -h/2; y < h/2; y += scl) {
      let n = noise(xoff, yoff, zoff); 

      // deformación de pliegues
      let angle = n * TWO_PI * 4;
      let r = map(n, 0, 1, 10, 80);

      // paleta de colores tipo carne-amarillo-rojizo
      let c1 = color(245, 205, 140, 180);
      let c2 = color(230, 180, 120, 180);
      let c3 = color(200, 120, 100, 200);
      let c = lerpColor(c1, c2, n);
      if (n > 0.7) {
        c = lerpColor(c2, c3, (n - 0.7) * 3);
      }

      fill(c);
      ellipse(x + cos(angle) * r, y + sin(angle) * r, scl * 1.5, scl * 1.2);

      yoff += 0.08;
    }
    xoff += 0.08;
  }

  zoff += 0.01; // animación lenta, genera vibración orgánica
}


// === Tab: lines ===
function distSq(p1, p2) {
  return Math.pow(p1[0] - p2[0], 2) + Math.pow(p1[1] - p2[1], 2)
}

const linesStateDefaults = () => ({
  done: false,
  doneAdding: false,
  colorIndex: 0,
  linesDrawn: 0,
  longLines: [],
  failsCount: 0,
  lastPoint: null,
  longLinesSaved: [],
  redrawing: false,
  redrawnCount: 0,
  _currentLine: [],
  _currentLineLength: 0,
})

class Lines {
  stepRate = 2000
  stepMult = 2
  alphaThreshold = 150
  longLineRatio = 0.4
  lineWidth = 4
  newPixelRadius = 50

  len = {
    minStart: 100,
    minEnd: 10,
    minReduceBy: 1,
    maxForColor: 300,
    max: 300,
  }
  redraw = false
  wiggle = {
    withinLine: 0.88,
    onLinePointFail: 0.05,
    betweenLine: 0.1,
    nLines: 2,
    max: 1.6,
    dir: 'random',
  }
  failsUntil = {
    stop: 1000,
    moveLook: 100,
    forceMoveLook: 300,
    reduceMinLen: 400,
  }
  tries = {
    pixel: 10,
    linePoint: 10,
  }
  colors = {
    sort: 'luminance',
    pattern: 'length',
    move: 0.0001,
    mixSpace: 'hsl',
    sortDir: '-',
    // shadowAmt: 0,
    // shadowAlpha: 0,
    // shadowOffset: [0, 0],
  }

  state = {
    _currentLineLength: 0,
    _currentLine: [],
    linesDrawn: 0,
    lineLookPoint: [0, 0],
    lastPoint: null,
    longLines: [],
    angle: 0,
    lineAngle: 0,
    redrawnCount: 0,
    redrawing: false,
    longLinesSaved: [],
    done: false,
    doneAdding: false,
    colorIndex: 0,
    failsCount: 0,
    currentMinLen: this.len.minStart,
  }

  constructor(g, pd, palette) {
    this.width = g.width
    this.height = g.height
    this.rect = new Rectangle(0, 0, this.width, this.height)
    this.pd = pd
    this.g = g
    this.g.pixelDensity(this.pd)
    this.loadPixels()

    this.state.angle = Math.random() * Math.PI * 2
    this.state.lineAngle = this.state.angle
    this.state.lineLookPoint = [Math.floor(random(this.width)), Math.floor(random(this.height))]

    this.palette = palette
    this.sortColors()
  }

  get done() {
    return this.state.done
  }

  setLine(line = [], isBeingRedrawn = false) {
    if (!isBeingRedrawn && line.length > 2) {
      if (distSq(line[0], line[line.length - 1]) > (this.width * this.longLineRatio) ** 2) {
        this.state.longLines.push([...line])

        this.state.longLinesSaved.push([...line])
      }
    }
    this.state.lastPoint = null
    this.state._currentLine = [...line]
    this.state._currentLineLength = this.state._currentLine.length
    this.state.failsCount = 0
  }

  sortColors() {
    this.currentPalette = [...this.palette]
    if (this.colors.sort === 'none') {
      return
    }
    this.currentPalette = sortPalette(this.currentPalette, this.colors.sort, this.colors.sortDir)
  }

  maybeGetNewPixel() {
    let [x, y] = this.state.lineLookPoint
    let tries = 0
    while (tries < this.tries.pixel) {
      let [nx, ny] =
        this.newPixelMethod === 'circle'
          ? randomInCircle(x, y, this.newPixelRadius)
          : this.newPixelMethod === 'rect'
          ? randomInSquare(x, y, this.newPixelRadius)
          : this.rect.getRandom()
      if (this.rect.contains(nx, ny) && this.isBlankIshPx(nx, ny)) {
        return [nx, ny]
      }
      tries++
    }
    return false
  }

  isBlankIshPx(x, y) {
    let ind = pixelIndex(Math.round(x), Math.round(y), this.width, this.pd)
    return this.g.pixels[ind + 3] < this.alphaThreshold
  }

  getLinePoints(x, y) {
    let curX = x
    let curY = y
    let points = []
    var tries = 0

    while (points.length < this.len.max && tries < this.tries.linePoint) {
      let nextX = curX + Math.cos(this.state.lineAngle) * this.stepMult
      let nextY = curY + Math.sin(this.state.lineAngle) * this.stepMult

      if (nextX < 0 || nextX >= this.width || nextY < 0 || nextY >= this.height) {
        break
      } else if (!this.isBlankIshPx(nextX, nextY)) {
        this.state.lineAngle += randomAngle(this.wiggle.onLinePointFail)
        tries++
      } else {
        points.push([curX, curY])
        curX = nextX
        curY = nextY
        let angleDiff = this.state.lineAngle - this.state.angle

        if (this.wiggle.max > 0 && Math.abs(angleDiff) > this.wiggle.max) {
          this.state.lineAngle += random(this.wiggle.withinLine) * (angleDiff > 0 ? -1 : 1)
        } else {
          this.state.lineAngle += randomAngle(this.wiggle.withinLine)
        }

        tries = 0
      }
    }

    if (points.length < this.state.currentMinLen) {
      return false
    }

    return points
  }

  addFail() {
    let state = this.state
    state.failsCount++
    if (state.failsCount > this.failsUntil.moveLook && state.longLines.length) {
      let longLine = state.longLines.shift()
      state.lineLookPoint = longLine[Math.floor(longLine.length / 2)]
    } else if (state.failsCount > this.failsUntil.forceMoveLook) {
      state.lineLookPoint = this.rect.getRandom()
    }

    if (state.failsCount > this.failsUntil.reduceMinLen) {
      this.state.currentMinLen = Math.max(
        this.state.currentMinLen - this.len.minReduceBy,
        this.len.minEnd
      )
    }

    if (state.failsCount > this.failsUntil.stop && this.state.currentMinLen === this.len.minEnd) {
      state.doneAdding = true
      state.longLinesSaved.sort((a, b) => b.length - a.length)
      state.redrawnCount = 0
    }
  }

  maybeGetNewLine() {
    while (true) {
      let pixel = this.maybeGetNewPixel()
      if (!pixel) break

      let [x1, y1] = pixel
      var points = this.getLinePoints(x1, y1)

      if (!points) break

      this.setLine(points)
      return true
    }
    this.addFail()
    return false
  }

  finishLine() {
    this.state.linesDrawn++
    this.loadPixels()
    this.setLine()
    if (this.state.linesDrawn % this.wiggle.nLines === 0) {
      this.getNewAngle()
    }
    this.state.lineAngle = this.state.angle

    if (
      this.redraw &&
      this.state.linesDrawn > this.redraw.after &&
      this.state.linesDrawn % this.redraw.rate === 0 &&
      this.state.redrawnCount < this.state.longLinesSaved.length * this.redraw.maxMult
    ) {
      this.doRedraw()
    }
  }

  getNewAngle() {
    if (this.wiggle.dir === 'random') {
      this.state.angle += randomAngle(this.wiggle.betweenLine)
    } else {
      this.state.angle +=
        randomAngle(this.wiggle.betweenLine, true) * (this.wiggle.dir === '+' ? 1 : -1)
    }
  }

  doRedraw() {
    this.state.redrawing = true
    this.state.redrawnCount++
    this.setLine(
      this.state.longLinesSaved[this.state.redrawnCount % this.state.longLinesSaved.length],
      true
    )
  }

  doEndRedraw() {
    if (this.redraw && this.state.redrawnCount < this.state.longLinesSaved.length) {
      this.doRedraw()
    } else {
      this.state.done = true
    }
  }

  setColor() {
    let color
    if (this.colors.pattern === 'step') {
      this.state.colorIndex += this.colors.move
      if (this.state.colorIndex >= this.currentPalette.length) {
        this.state.colorIndex = 0
      }
      var c1 = this.currentPalette[Math.floor(this.state.colorIndex)]
      var c2 = this.currentPalette[Math.ceil(this.state.colorIndex)]
      if (!c2) c2 = this.currentPalette[0]
      color = chroma.mix(c1, c2, this.state.colorIndex % 1, this.colors.mixSpace)
    } else {
      let len = this.state._currentLineLength
      let max = Math.min(this.len.maxForColor, this.len.max)
      let mix = (len - this.len.minEnd) / (max - this.len.minEnd)
      mix = 1 - Math.pow(1 - mix, 4) // ease out quart
      color = chroma(this.currentPalette[Math.floor(mix * (this.currentPalette.length - 1))])
    }

    if (this.colors.shadowAmt) {
      let shadow = color.alpha(this.colors.shadowAlpha).hex()
      setShadow(this.g, shadow, this.lineWidth * this.colors.shadowAmt, this.colors.shadowOffset)
    }
    this.g.stroke(color.hex())
    this.g.strokeWeight(this.lineWidth)
  }

  lineStep() {
    if (this.state._currentLine.length < 2) return
    let [x1, y1] = this.state.lastPoint ?? this.state._currentLine[0]
    this.setColor()
    let [x2, y2] = this.state._currentLine[1]

    this.g.line(x1, y1, x2, y2)
    this.state.lastPoint = [x2, y2]
    this.state._currentLine.shift()
    if (this.state._currentLine.length < 2) {
      this.finishLine()
    }
  }

  update(delta) {
    let steps = Math.round((delta / 1000) * this.stepRate)
    while (steps > 0 && !this.state.done) {
      if (this.state._currentLine.length >= 2) {
        this.lineStep()
        steps--
        continue
      }
      if (this.state.doneAdding) {
        this.doEndRedraw()
      } else {
        this.maybeGetNewLine()
      }

      if (this.state.done) break
    }
    return this.state.done
  }

  loadPixels() {
    this.g.loadPixels()
  }

  reset(angle, lookPoint) {
    this.g.clear()
    this.loadPixels()
    this.sortColors()

    let newangle = angle || Math.random() * Math.PI * 2
    let newPoint = lookPoint || this.rect.getRandom()
    this.state = {
      ...linesStateDefaults(),
      angle: newangle,
      lineAngle: newangle,
      lineLookPoint: newPoint,
      currentMinLen: this.len.minStart,
    }
  }
}


// === Tab: utils ===
const randomInSquare = (cx, cy, radius) => {
  let x = random(cx - radius, cx + radius)
  let y = random(cy - radius, cy + radius)
  return [Math.floor(x), Math.floor(y)]
}

const randomInCircle = (cx, cy, radius) => {
  var angle = random(0, Math.PI * 2)
  var r = random(0, radius)
  var x = cx + r * Math.cos(angle)
  var y = cy + r * Math.sin(angle)
  return [Math.floor(x), Math.floor(y)]
}

const pixelIndex = (x, y, w, pd) => {
  return (y * w * pd + x) * 4 * pd
}

const isPixelBlank = (pixels, index, alphaThreshold = 255) => {
  return pixels[index + 3] < alphaThreshold
}

const randomAngle = (range, onlyPositive = false) => {
  if (onlyPositive) return random(0, range)
  return random(-range * 0.5, range * 0.5)
}

const setShadow = (g, color, blur, offset) => {
  g.drawingContext.shadowColor = color
  g.drawingContext.shadowBlur = blur
  g.drawingContext.shadowOffsetX = offset[0]
  g.drawingContext.shadowOffsetY = offset[1]
}

const sortPalette = function (colors, sort, dir = 'asc') {
  let palette = [...colors]

  if (sort === 'temperature') {
    palette.sort((a, b) => chroma(a).temperature() - chroma(b).temperature())
  } else if (sort === 'luminance') {
    palette.sort((a, b) => chroma(a).luminance() - chroma(b).luminance())
  } else {
    let key = sort === 'hue' ? 'hsl.h' : sort === 'saturation' ? 'hsl.s' : 'hsl.l'
    palette.sort((a, b) => chroma(a).get(key) - chroma(b).get(key))
  }

  if (dir === 'desc' || dir === '-') {
    palette.reverse()
  }

  return palette
}


// === Tab: rectangle ===
class Rectangle {
  constructor(x, y, w, h) {
    this.x = x
    this.y = y
    this.w = w
    this.h = h
  }

  contains(x, y) {
    return x >= this.x && x <= this.x + this.w && y >= this.y && y <= this.y + this.h
  }

  intersects(range) {
    return !(
      range.x > this.x + this.w ||
      range.x + range.w < this.x ||
      range.y > this.y + this.h ||
      range.y + range.h < this.y
    )
  }

  getRandom(integer = true) {
    var x = random(this.x, this.x + this.w)
    var y = random(this.y, this.y + this.h)
    return integer ? [Math.floor(x), Math.floor(y)] : [x, y]
  }
}


// === Tab: glslnoise ===
// simplex noise from patricio gonzalez vivo https://thebookofshaders.com/edit.php#11/iching-03.frag

let snoise = /* glsl */ `
vec3 random3(vec3 c) {
    float j = 4096.0 * sin(dot(c, vec3(17.0, 59.4, 15.0)));
    vec3 r;
    r.z = fract(512.0 * j);
    j *= .125;
    r.x = fract(512.0 * j);
    j *= .125;
    r.y = fract(512.0 * j);
    return r - 0.5;
}

const float F3 = 0.3333333;
const float G3 = 0.1666667;
float snoise(vec3 p) {

  vec3 s = floor(p + dot(p, vec3(F3)));
  vec3 x = p - s + dot(s, vec3(G3));

  vec3 e = step(vec3(0.0), x - x.yzx);
  vec3 i1 = e * (1.0 - e.zxy);
  vec3 i2 = 1.0 - e.zxy * (1.0 - e);

  vec3 x1 = x - i1 + G3;
  vec3 x2 = x - i2 + 2.0 * G3;
  vec3 x3 = x - 1.0 + 3.0 * G3;

  vec4 w, d;

  w.x = dot(x, x);
  w.y = dot(x1, x1);
  w.z = dot(x2, x2);
  w.w = dot(x3, x3);

  w = max(0.6 - w, 0.0);

  d.x = dot(random3(s), x);
  d.y = dot(random3(s + i1), x1);
  d.z = dot(random3(s + i2), x2);
  d.w = dot(random3(s + 1.0), x3);

  w *= w;
  w *= w;
  d *= w;

  return dot(d, vec4(52.0));
}

`

// === Tab: glsl ===

let vert = /* glsl */ `
precision mediump float;
uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;

attribute vec3 aPosition;
attribute vec2 aTexCoord;
varying vec2 vTexCoord;
varying float vWave;

uniform float uTime;

${snoise}

void main() {
  vTexCoord = aTexCoord;

  vec3 noisePos = vec3(aTexCoord.x * 50.0, aTexCoord.y * 234.0, uTime);
  float wave = snoise(noisePos); 
  vWave = wave;

  vec4 positionVec4 = vec4(aPosition, 1.0);
  gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;
}
`

let frag = /* glsl */ `
precision mediump float;
uniform sampler2D uTex;
uniform float uTime;
varying vec2 vTexCoord;

${snoise}

void main() {
  vec2 st = vTexCoord;
  float angle = 1.9 * sin( st.x + uTime);
  float radius = snoise(vec3(st.x * 50.0 - uTime * 0.3, st.y * 18.0 - uTime * 0.3 , uTime * 0.1)) * 0.05;
  st.x -= cos(angle) * radius * 0.2;
  st.y += sin(angle) * radius * 0.5;


  vec4 color = texture2D(uTex, st);
  gl_FragColor = color;
}
`

// === Tab: ease ===
let easing = {
	inSine: (x) => 1 - Math.cos((x * Math.PI) / 2),
	outSine: (x) => Math.sin((x * Math.PI) / 2),
	inOutSine: (x) => -0.5 * (Math.cos(Math.PI * x) - 1),
	inQuad: (x) => x * x,
	outQuad: (x) => 1 - (1 - x) * (1 - x),
	inOutQuad: (x) => (x < 0.5 ? 2 * x * x : -1 + (4 - 2 * x) * x),
	inCubic: (x) => x * x * x,
	outCubic: (x) => 1 - Math.pow(1 - x, 3),
	inOutCubic: (x) => (x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2),
	inQuart: (x) => x * x * x * x,
	outQuart: (x) => 1 - Math.pow(1 - x, 4),
	inOutQuart: (x) => (x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2),
	inQuint: (x) => x * x * x * x * x,
	outQuint: (x) => 1 - Math.pow(1 - x, 5),
	inOutQuint: (x) => (x < 0.5 ? 16 * x * x * x * x * x : 1 - Math.pow(-2 * x + 2, 5) / 2),
	inExpo: (x) => (x === 0 ? 0 : Math.pow(2, 10 * x - 10)),
	outExpo: (x) => (x === 1 ? 1 : 1 - Math.pow(2, -10 * x)),
	inCirc: (x) => 1 - Math.sqrt(1 - x * x),
	outCirc: (x) => Math.sqrt(1 - Math.pow(x - 1, 2)),
	inOutCirc: (x) =>
		x < 0.5 ?
		(1 - Math.sqrt(1 - Math.pow(2 * x, 2))) / 2 :
		(Math.sqrt(1 - Math.pow(-2 * x + 2, 2)) + 1) / 2,
}

